    def aligned(p, q):
        dr = abs(p[0] - q[0])
        dc = abs(p[1] - q[1])
        return dr == 0 or dc == 0 or dr == dc

    def segment(p, q):
        dr = q[0] - p[0]
        dc = q[1] - p[1]
        steps = max(abs(dr), abs(dc))
        sr = (dr > 0) - (dr < 0)
        sc = (dc > 0) - (dc < 0)
        return [(p[0] + i * sr, p[1] + i * sc)
                for i in range(steps + 1)]

    paths = {}
    for color, ps in points.items():
        edges = set()
        for p in ps:
            candidates = []
            for q in ps:
                if q != p and aligned(p, q):
                    dr = p[0] - q[0]
                    dc = p[1] - q[1]
                    candidates.append((dr * dr + dc * dc, q))
            candidates.sort()
            if candidates:
                cutoff = candidates[min(1, len(candidates) - 1)][0]
                for distance, q in candidates:
                    if distance <= cutoff:
                        edges.add(tuple(sorted((p, q))))

        cells = set()
        for p, q in edges:
